A base declara o contrato — o método existe — e cada filha implementa o comportamento:

```js
class Figura {
  area() {
    throw new Error('implemente area() na subclasse'); // contrato
  }
}

class Circulo extends Figura {
  constructor(raio) {
    super();
    this.raio = raio;
  }
  area() {
    return Math.PI * this.raio ** 2; // jeito do círculo
  }
}

class Quadrado extends Figura {
  constructor(lado) {
    super();
    this.lado = lado;
  }
  area() {
    return this.lado ** 2; // jeito do quadrado
  }
}
```

Agora um código que não sabe (e não precisa saber) qual figura está na mão:

```js
function somarAreas(figuras) {
  let soma = 0;
  for (const figura of figuras) {
    soma += figura.area(); // cada um responde do seu jeito
  }
  return soma;
}

const total = somarAreas([new Circulo(5), new Quadrado(4)]);
```

Repare: `somarAreas` nunca pergunta "é círculo ou quadrado?" — não há `if` por tipo. Ela trata todas pela forma comum ("sou uma figura e sei calcular minha área"). Isso é o polimorfismo em ação: mesmo método, comportamentos diferentes, código único.

**Estratégia:** quando um código precisar se comportar diferente por tipo com `if (objeto instanceof X)`, pergunte: será que esse "jeito de cada um" não deveria ser um método na própria classe?

code.code:
// Passos 1 a 3: mesmo método, comportamentos diferentes.
class Pagamento {
  calcularTaxa() {
    // contrato: toda forma de pagamento precisa responder a isto
    throw new Error('implemente calcularTaxa() na subclasse');
  }
}

class Pix extends Pagamento {
  constructor(valor) {
    super();
    this.valor = valor;
  }
  calcularTaxa() {
    return 0; // pix não cobra taxa
  }
}

class Cartao extends Pagamento {
  constructor(valor) {
    super();
    this.valor = valor;
  }
  calcularTaxa() {
    return this.valor * 0.05; // cartão cobra 5%
  }
}

// Passo 4: código genérico — trata todos pela forma comum, sem if por tipo.
function totalDeTaxas(pagamentos) {
  let total = 0;
  for (const pagamento of pagamentos) {
    total += pagamento.calcularTaxa(); // cada um responde do seu jeito
  }
  return total;
}

// Passo 5: um Pix e um Cartão entram na mesma lista.
const pix = new Pix(1000);       // taxa: 0
const cartao = new Cartao(1000); // taxa: 50
console.log(pix.calcularTaxa());        // imprime: 0
console.log(cartao.calcularTaxa());     // imprime: 50
console.log(totalDeTaxas([pix, cartao])); // imprime: 50
